using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "EldritchConnectionEffect", menuName = "Data/Battle/Effects/Enemy/EldritchConnection Effect")]
public class EldritchConnectionEffect : Effect
{
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public int DealPurificationToBoss(int amount)
	{
		GameObject corruptionSource = currentCorruptedAnimals.GetCorruptionSource();
		if (corruptionSource != null)
		{
			int amount2 = ((amount == EffectsValues.INFINITY_PURIFY) ? amount : Mathf.CeilToInt((float)amount / 2f));
			corruptionSource.GetComponent<CorruptionStats>().Purify(amount2, null, (amount == EffectsValues.INFINITY_PURIFY) ? CorruptionPurifyModifierEnum.ELDRITCHCONNECTIONINFINITY : CorruptionPurifyModifierEnum.NONE, playSFX: true);
		}
		return amount;
	}
}
